1	import { db } from "./db";
2	
3	// Credits already cap spend per build, but nothing stops a broken or
4	// malicious client from firing many rapid requests before a human notices —
5	// and a free, unmetered *.kodely.site subdomain is a spam/phishing vector
6	// independent of credit spend. These are coarse, cheap safety nets, not a
7	// content-moderation system (there is no classifier here — a page can still
8	// be abusive content and pass both checks; that's a separate, harder problem
9	// left for a dedicated moderation pass, not faked here with a weak heuristic).
10	
11	const GENERATE_LIMIT = 20; // per user, per rolling hour
12	const PUBLISH_LIMIT = 15; // new (first-time) publishes per user, per rolling day
13	
14	export async function checkGenerateRateLimit(
15	  userId: string,
16	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
17	  const since = new Date(Date.now() - 60 * 60_000);
18	  const count = await db.build.count({
19	    where: { project: { userId }, createdAt: { gte: since } },
20	  });
21	  if (count < GENERATE_LIMIT) return { allowed: true };
22	  return { allowed: false, retryAfterSeconds: 3600 };
23	}
24	
25	export async function checkPublishRateLimit(
26	  userId: string,
27	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
28	  const since = new Date(Date.now() - 24 * 60 * 60_000);
29	  // Counts DISTINCT projects touched by a publish in the window, not publish
30	  // events — republishing the same project repeatedly still counts once.
31	  // That's the right shape: the abuse case is many distinct spam subdomains,
32	  // not heavy iteration on one real site (which credits already gate).
33	  const count = await db.project.count({
34	    where: { userId, publishedAt: { gte: since } },
35	  });
36	  if (count < PUBLISH_LIMIT) return { allowed: true };
37	  return { allowed: false, retryAfterSeconds: 86_400 };
38	}
