// THROWAWAY — builds fixtures for real with vite, then moderates the dist output.
// Builds inside the foundation dir so plain node_modules resolution works
// (the junction lib/build-site.ts makes is broken on this particular machine,
// which is a local env quirk, not something this change touches).
import { spawnSync } from "node:child_process";
import { mkdir, writeFile, rm, readdir, readFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { moderateForPublish, type ModerationInput } from "./lib/moderation";
import { FIXTURES, type Fixture } from "./__modfixtures.mts";

const FOUNDATION = "C:\\Users\\edmem\\kodely-foundation";

async function buildReal(files: Record<string, string>): Promise<ModerationInput[]> {
  const work = join(FOUNDATION, "__work");
  await rm(work, { recursive: true, force: true });
  for (const [p, c] of Object.entries(files)) {
    const full = join(work, p);
    await mkdir(dirname(full), { recursive: true });
    await writeFile(full, c, "utf8");
  }
  const r = spawnSync(process.execPath, [join(FOUNDATION, "node_modules", "vite", "bin", "vite.js"), "build"], {
    cwd: work,
    encoding: "utf8",
  });
  if (r.status !== 0) throw new Error((r.stderr || r.stdout || "").slice(-600));
  const out: ModerationInput[] = [];
  async function walk(dir: string, prefix: string) {
    for (const e of await readdir(dir, { withFileTypes: true })) {
      const full = join(dir, e.name);
      const rel = prefix ? `${prefix}/${e.name}` : e.name;
      if (e.isDirectory()) await walk(full, rel);
      else if (/\.(html|js|css|json|svg|txt|map)$/.test(e.name)) out.push({ path: rel, content: await readFile(full, "utf8") });
    }
  }
  await walk(join(work, "dist"), "");
  await rm(work, { recursive: true, force: true });
  return out;
}

let failures = 0;
const COLOR = { high: "\x1b[31m", medium: "\x1b[33m", low: "\x1b[90m" };

for (const fx of FIXTURES as Fixture[]) {
  let dist: ModerationInput[];
  try {
    dist = await buildReal(fx.files);
  } catch (e) {
    console.log(`\x1b[41mBUILD FAIL\x1b[0m ${fx.name}\n${(e as Error).message}`);
    failures++;
    continue;
  }
  // dist ONLY — proves the rules survive minification without help from source.
  const res = await moderateForPublish(dist);
  const highs = res.findings.filter((f) => f.severity === "high");
  const ok = fx.expectHigh === highs.length > 0;
  if (!ok) failures++;
  console.log(`${ok ? "\x1b[32mPASS\x1b[0m" : "\x1b[41mFAIL\x1b[0m"} [dist only] ${fx.name}   (${dist.map((d) => d.path).join(", ")})`);
  for (const f of res.findings) {
    console.log(`        ${COLOR[f.severity]}${f.severity.toUpperCase().padEnd(6)}\x1b[0m ${f.rule.padEnd(38)} ${f.path}`);
    console.log(`               ${COLOR[f.severity]}${f.evidence.slice(0, 160)}\x1b[0m`);
  }
  if (res.findings.length === 0) console.log("        (no findings)");
  console.log();
}
console.log(failures === 0 ? "\x1b[32mALL DIST EXPECTATIONS MET\x1b[0m" : `\x1b[31m${failures} FAILURES\x1b[0m`);
process.exit(failures === 0 ? 0 : 1);

